Translate("deDE", "teldrassil", {
	title = "Teldrassil",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Teldrassil ist der neue Weltbaum der {link:night-elves}Nachtelfen{/link} und das Land, das auf ihm wächst. Er erhebt sich vor der Nordküste von {link:kalimdor}Kalimdor{/link} aus dem Meer, so gewaltig, dass ganze Wälder, Seen und Dörfer auf seinen Ästen ruhen. An seiner Krone steht die Stadt {link:darnassus}Darnassus{/link}. Seine Lichtungen werden von Mondbrunnen erhellt und von den {link:sentinels}Schildwachen{/link} bewacht, und einem Neuankömmling erscheint er als der friedlichste Ort der Welt. Wer dort lebt, weiß es besser. Etwas stimmt nicht mit dem Baum, und mit jeder Jahreszeit werden die Zeichen schwerer zu übersehen.]=],
		},
		{
			title = "Der Weltbaum",
			text = [=[Nach der {link:battle-of-mount-hyjal}Schlacht am Berg Hyjal{/link} blieben die {link:night-elves}Nachtelfen{/link} ohne ihre alte Stärke zurück. {link:nordrassil}Nordrassil{/link} hatte seine Kraft aufgewendet, um {link:archimonde}Archimonde{/link} zu vernichten, und mit ihr verloren die Kaldorei ihre Unsterblichkeit. {link:malfurion-stormrage}Malfurion Stormrage{/link} ging in den {link:emerald-dream}Smaragdgrünen Traum{/link} und kehrte nicht zurück. In seiner Abwesenheit übernahm Erzdruide {link:fandral-staghelm}Fandral Staghelm{/link} die Führung der Druiden. Er überzeugte den Zirkel der Urtume in der {link:darkshore}Dunkelküste{/link}, dass die Zeit gekommen sei, wieder aufzubauen und zurückzugewinnen, was verloren war. Mit der Zustimmung des Zirkels ließen er und die mächtigsten Druiden seines Ordens jenseits der Küste einen neuen Baum wachsen.

Als er gewachsen war, bat Fandral die großen Drachen, ihn zu segnen, wie sie einst Nordrassil gesegnet hatten. Nozdormu, der Herr der Zeit, wies ihn ab und tadelte seinen Hochmut. Auch {link:alexstrasza}Alexstrasza{/link}, die Lebensbinderin, wies ihn ab. Ohne ihre Gaben ist das Wachstum von Teldrassil fehlerhaft und unberechenbar gewesen, und die Nachtelfen haben ihr unvergängliches Leben nicht zurückgewonnen.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Teldrassil ist die Heimat der meisten Kaldorei, die den Krieg überlebten. Junge Druiden, Priesterinnen und {link:sentinels}Schildwachen{/link} beginnen ihren Dienst in {link:shadowglen}Shadowglen{/link} und {link:dolanaar}Dolanaar{/link} und steigen dann nach {link:darnassus}Darnassus{/link} hinauf. Doch der Wald ist krank. Die {link:gnarlpine-furbolgs}Knarzklauen-Furbolgs{/link}, einst sanfte Freunde der Elfen, sind verwildert. Holzlinge erheben sich zornig aus dem Boden und tragen Geschwülste. {link:harpies}Harpyien{/link} nisten um den Orakelbaum, {link:satyrs}Satyrn{/link} verbergen sich in seinen Höhlen, und ein Teufelsmoos breitet sich unter Bestien und {link:furbolgs}Furbolgs{/link} gleichermaßen aus. Die Druiden untersuchen jedes neue Übel der Reihe nach. Der Erzdruide trägt die Last von alledem, und er trägt sie nicht leichtfertig.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die {link:night-elves}Nachtelfen{/link}.{/b} Druiden, Priesterinnen der Elune, {link:sentinels}Schildwachen{/link}, Jäger und Handwerker, die in zwischen den Bäumen gewobenen Dörfern leben.
• {b}Die {link:gnarlpine-furbolgs}Knarzklauen-Furbolgs{/link}.{/b} Ein wahnsinnig gewordener Stamm, der aus der {link:gnarlpine-hold}Höhle der Knarzklauen{/link} und den Grabhügeln heraus plündert.
• {b}Holzlinge und Grells.{/b} Geschöpfe des Baumes selbst, viele von ihnen verderbt.
• {b}{link:harpies}Harpyien{/link} der Blutfeder.{/b} Sie nisten in den westlichen Lichtungen.
• {b}{link:satyrs}Satyrn{/link}.{/b} Einige dieser gefallenen Elfen lauern an verborgenen Orten.]=],
		},
		{
			title = "Überlieferungen des Baumes",
			text = [=[• Die Mondbrunnen von Teldrassil bergen Wasser, das aus dem uralten {link:well-of-eternity}Brunnen der Ewigkeit{/link} geschöpft wurde. Die Druiden nutzen sie, die {link:sentinels}Schildwachen{/link} verehren sie als Schreine der Elune, und jede Zauberei ist in ihrer Nähe verboten.
• Der älteste und stärkste Mondbrunnen liegt unter dem Orakelbaum, der auf seine eigene langsame Weise zu den Ältesten der Kaldorei spricht.
• Pflanzen, die man nie zuvor auf dem Baum gesehen hat, sind dort gesprossen, manche aus so fernen Landen wie den {link:swamp-of-sorrows}Sümpfen des Elends{/link}, und sie reagieren seltsam mit seinem Boden.]=],
		},
	},
})

Translate("deDE", "shadowglen", {
	title = "Shadowglen",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Shadowglen ist ein geschütztes Tal im Nordosten von {link:teldrassil}Teldrassil{/link}, wo viele junge Kaldorei ihre ersten Schritte im Dienst tun. In seinem Herzen wächst der große Baum {link:aldrassil}Aldrassil{/link}, und nördlich von ihm schimmert ein Mondbrunnen. {link:conservator-ilthalaine}Bewahrer Ilthalaine{/link} hält das Gleichgewicht seiner Tiere. Das Tal ist nicht so sicher, wie es aussieht. Vom Teufelsmoos befallene Grells streifen an seinem Westrand umher, wo die {link:gnarlpine-furbolgs}Knarzklauen{/link} einst in Frieden lebten. Nördlich des Tals liegt die Schattenweberhöhle, wo Webwood-Spinnen, die auf dem Weltbaum riesig geworden sind, ihre Nester spinnen.]=],
		},
	},
})

Translate("deDE", "aldrassil", {
	title = "Aldrassil",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Aldrassil ist der große Baum im Zentrum von {link:shadowglen}Shadowglen{/link}, ausgehöhlt und zu einer Wohnstatt für die Lehrer der Jungen gewachsen. Lehrer jeder Berufung haben Räume entlang seiner gewundenen Rampen. In seiner höchsten Kammer sitzt {link:tenaron-stormgrip}Tenaron Stormgrip{/link}, der jeden Neuankömmling ausschickt, um Wasser aus dem nahen Mondbrunnen zu holen, und so beginnt, die Geschichte von {link:teldrassil}Teldrassil{/link} zu erzählen. Der Gelehrte {link:gilshalan-windwalker}Gilshalan Windwalker{/link} arbeitet an seinem Fuß und erforscht die Spinnen der Schattenweberhöhle.]=],
		},
	},
})

Translate("deDE", "dolanaar", {
	title = "Dolanaar",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Dolanaar ist das Dorf an der Straße, auf halbem Weg zwischen {link:shadowglen}Shadowglen{/link} und {link:darnassus}Darnassus{/link}. Seine Häuser sind aus lebendem Holz um einen Mondbrunnen gewachsen, an dem {link:corithras-moonrage}Corithras Moonrage{/link} die Geschichte fortsetzt, die {link:tenaron-stormgrip}Tenaron{/link} begann. Gastwirtin Keldamyr bietet Reisenden Rast. Druiden wie {link:athridas-bearmantle}Athridas Bearmantle{/link} und {link:tallonkai-swiftroot}Tallonkai Swiftroot{/link} beobachten von hier aus die Nöte des Waldes, und die {link:sentinel-kyra-starsong}Schildwache Kyra Starsong{/link} schickt ihre Schwestern die Straßen entlang. Dolanaar ist stolz auf seinen guten Ruf, und seine Bewohner behalten gewisse Schande lieber für sich.]=],
		},
	},
})

Translate("deDE", "fel-rock", {
	title = "Teufelsfels",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Teufelsfels ist eine Höhle gleich nördlich von {link:dolanaar}Dolanaar{/link}. Sein Name ist zu einer harten Wahrheit geworden. Der {link:satyrs}Satyr{/link} {link:lord-melenas}Lord Melenas{/link} schlug in seinen Tiefen sein Lager auf und scharte eine Bande von Grellkriegern um sich. Die Druiden von Dolanaar halten es für eine tiefe Schmach, dass ein solches Geschöpf so nahe an ihrem Dorf haust, und sie haben versucht, ihn im Stillen zu erledigen. Seine Ränke, das weiß man inzwischen, dienten einem dunkleren Herrn an anderer Stelle im Wald.]=],
		},
	},
})

Translate("deDE", "lake-al-ameth", {
	title = "Al'Amethsee",
	aliases = { "Al'Ameth" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Al'Amethsee liegt südlich von {link:dolanaar}Dolanaar{/link}, ein langgestrecktes Gewässer, umringt von Bäumen und Farnwedeln. An seinem Ostufer unterhält der Druide {link:denalan}Denalan{/link} ein Lager und einen Garten, wo er an den Samen der Holzlinge neue Erden erprobt. Am See zeigt sich die Krankheit dieser Geschöpfe am deutlichsten. Junge Holzlinge sprießen wild an seinen Ufern, und in einer Höhle an seinem Südufer haust {link:oakenscowl}Oakenscowl{/link}, einst ein Anführer seiner Art und nun eine Quelle der Verderbnis.]=],
		},
	},
})

Translate("deDE", "starbreeze-village", {
	title = "Starbreeze",
	aliases = { "Starbreeze" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Starbreeze liegt im Osten von {link:teldrassil}Teldrassil{/link}, jenseits der Straße von {link:dolanaar}Dolanaar{/link}. Es war ein ruhiger Ort, und gleich außerhalb schimmert noch immer ein Mondbrunnen. Dann kamen die {link:gnarlpine-furbolgs}Knarzklauen{/link}. Die {link:furbolgs}Furbolgs{/link} überfielen den Wärter {link:gaerolas-talvethren}Gaerolas Talvethren{/link} auf seinem Weg zum Grabhügel und plünderten das Dorf. Häuser stehen leer, die Schätze ihrer Besitzer in den Kommoden zurückgelassen. Die Furbolgs, die in Starbreeze geblieben sind, haben sich ganz ihrem Wahnsinn hingegeben.]=],
		},
	},
})

Translate("deDE", "ban-ethil-barrow-den", {
	title = "Grabhügel von Ban'ethil",
	aliases = { "Ban'ethil" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Grabhügel von Ban'ethil liegt westlich von {link:dolanaar}Dolanaar{/link}, unter den Wurzeln des Waldes. Hier schlafen die Druiden der Kralle, und ihre Geister wandeln im {link:emerald-dream}Smaragdgrünen Traum{/link}, getreu ihrem Pakt mit Ysera. Die {link:gnarlpine-furbolgs}Knarzklauen{/link} sind eingedrungen. Ihre Schamanen haben gelernt, den Geist eines schlafenden Druiden von seinem Körper zu trennen und das leere Fleisch gegen Eindringlinge zu hetzen. Die Schläfer können nur mit den Relikten des Erwachens geweckt werden, die in heiligen Truhen darin verwahrt sind. Selbst Boten des Orakelbaums wurden hinabgeschleppt.]=],
		},
	},
})

Translate("deDE", "gnarlpine-hold", {
	title = "Höhle der Knarzklauen",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Höhle der Knarzklauen ist die Festung der {link:gnarlpine-furbolgs}Knarzklauen-Furbolgs{/link} im Südwesten von {link:teldrassil}Teldrassil{/link}. Hier haust ihr Häuptling, {link:ursal-the-mauler}Ursal der Zerfleischer{/link}, der sein Volk mit den Kräften des Teufelsmooses in den Wahnsinn treibt. Schamanen, Totemiker und Verteidiger des Stammes drängen sich in ihren Bauen, und gefangene Druiden werden dort unter dem Bann der {link:furbolgs}Furbolgs{/link} festgehalten. Was einst eine Heimat sanfter Wesen war, ist zum Herzen der Raserei des Stammes geworden.]=],
		},
	},
})

Translate("deDE", "pools-of-arlithrien", {
	title = "Teiche von Arlithrien",
	aliases = { "Arlithrien" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Teiche von Arlithrien liegen südöstlich der Straße nach {link:darnassus}Darnassus{/link}, eine Kette stiller Gewässer neben einem der Mondbrunnen von {link:teldrassil}Teldrassil{/link}. Die {link:sentinels}Schildwachen{/link} bestreiften sie einst mühelos. Nun greifen die {link:gnarlpine-furbolgs}Knarzklauen-Furbolgs{/link} jede Streife an, und der Pfad zum Brunnen ist eine Gefahr für jeden, der allein geht. Die ersten Berichte über ihre Angriffe hier wurden als Gerücht abgetan. Niemand tut sie mehr ab.]=],
		},
	},
})

Translate("deDE", "the-oracle-glade", {
	title = "Die Lichtung des Orakels",
	aliases = { "Lichtung des Orakels" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Lichtung des Orakels liegt im Nordwesten von {link:teldrassil}Teldrassil{/link}. In ihrem Herzen wächst der Orakelbaum, der über das Wachstum des Weltbaums wacht und seinen Rat an die Ältesten der Kaldorei sendet. Unter seinen Ästen liegt der erste und mächtigste Mondbrunnen von Teldrassil. {link:harpies}Harpyien{/link} der Blutfeder haben rings um {link:moonglade}die Lichtung{/link} genistet, und sie haben die Läuferinnen getötet, die die Botschaften des Baumes überbrachten. Eine kleine Schar von {link:sentinels}Schildwachen{/link} unter {link:sentinel-arynia-cloudsbreak}Arynia Cloudsbreak{/link} hält den Mondbrunnen gegen sie.]=],
		},
	},
})

Translate("deDE", "wellspring-lake", {
	title = "Wellspringsee",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Wellspringsee liegt im hohen Norden von {link:teldrassil}Teldrassil{/link}, und der Wellspring fließt von ihm aus durch den Wald. Die Holzlinge, die an seinen Ufern umherwandern, sind die verderbtesten auf dem Baum, bedeckt mit moosigen Geschwülsten voller Gift. An den nahen Nordgrenzen haust {link:lady-sathrah}Lady Sathrah{/link}, eine große Spinne, einst von Elune geliebt, deren silberne Fäden den heilenden Abendtau sammelten. Sie ist wahnsinnig geworden, und ihre Art mit ihr.]=],
		},
	},
})

Translate("deDE", "the-cleft", {
	title = "Die Kluft",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Kluft ist eine tiefe Falte im Wald nordwestlich von {link:dolanaar}Dolanaar{/link}. Nur wenige gehen freiwillig dorthin. Der {link:satyrs}Satyr{/link} Xethorr der Verruchte hat sie zu seiner Heimat gemacht, und auf sein Geheiß hin schmiedete {link:lord-melenas}Lord Melenas{/link} im {link:fel-rock}Teufelsfels{/link} seine Ränke. Xethorr hat die Spinnen von {link:teldrassil}Teldrassil{/link} seinem Willen unterworfen, und die besudelten Webwood-Spinnen der Kluft tragen das Teufelsmoos in ihrem Gift. Die Druiden von Dolanaar würden ihn lieber im Stillen jagen, als den Wald erfahren zu lassen, wie nahe er haust.]=],
		},
	},
})

Translate("deDE", "rut-theran-village", {
	title = "Rut'theran",
	aliases = { "Rut'theran" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Rut'theran liegt am Fuß von {link:teldrassil}Teldrassil{/link}, am Ufer, wo seine großen Wurzeln auf das Meer treffen. Es ist die Tür des Baumes zur Welt. Schiffe und Hippogryphen kommen und gehen von hier, und der Hippogryphenmeister Vesprystus trägt Reisende über das Wasser nach {link:auberdine}Auberdine{/link} in der {link:darkshore}Dunkelküste{/link}. Ein Portal hebt jene, die nach {link:darnassus}Darnassus{/link} wollen, hinauf in die Stadt. Die Fische dieser Gewässer sind groß und zahlreich, und die Hüter des Wissens des Zirkels des {link:cenarius}Cenarius{/link} unterhalten hier ebenfalls ein kleines Haus.]=],
		},
	},
})

Translate("deDE", "conservator-ilthalaine", {
	title = "Bewahrer Ilthalaine",
	subtitle = "Hüter des Gleichgewichts von Shadowglen",
	found = "Vor Aldrassil, in Shadowglen",
	hint = [=[Sprecht mit dem Bewahrer, der vor dem großen Baum von Shadowglen steht.]=],
	allegiance = "Nachtelfen · Shadowglen",
	aliases = { "Ilthalaine" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Bewahrer Ilthalaine hält das Gleichgewicht der Natur in {link:shadowglen}Shadowglen{/link}. Die Frühlingsregen waren in diesem Jahr heftig, und manche Tiere des Tals gediehen, während andere hungerten. Die Nachtsäbler und Distelkeiler sind zu zahlreich geworden, als dass das Land sie ernähren könnte. Ilthalaine gefällt die Antwort nicht, doch er gibt sie offen: Ihre Zahl muss verringert werden.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Ilthalaine lehrt die erste Lektion der Kaldorei: dass das Töten dem lebendigen Wald dienen kann, wenn es um des Gleichgewichts willen geschieht und nicht um des Gewinns willen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schickt die Jungen von {link:shadowglen}Shadowglen{/link} aus, um die Nachtsäbler und Distelkeiler zu dezimieren.
• Er weist jeden Neuankömmling an den Lehrer seiner Berufung in {link:aldrassil}Aldrassil{/link}.]=],
		},
	},
	mentions = {
		{ text = "Das Gleichgewicht der Natur" },
		{ text = "Das Gleichgewicht der Natur" },
	},
	bonds = {
		{ id = "melithar-staghelm", name = "Melithar Staghelm", note = "hält Wache im selben Tal" },
		{ id = "tarindrella", name = "Tarindrella", note = "eine Hüterin derselben Wälder" },
	},
})

Translate("deDE", "melithar-staghelm", {
	title = "Melithar Staghelm",
	subtitle = "Druide von Shadowglen",
	found = "Nahe dem Mondbrunnen vor Aldrassil",
	hint = [=[Sprecht mit dem Druiden, der in Shadowglen das Flüstern der Waldgeister hört.]=],
	allegiance = "Zirkel des Cenarius",
	aliases = { "Melithar" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Melithar Staghelm ist ein Druide von {link:shadowglen}Shadowglen{/link}, der dem Flüstern der Waldgeister lauscht. Durch sie erfuhr er, dass die Dryade {link:tarindrella}Tarindrella{/link} ins Tal zurückgekehrt war, obwohl man sie in den Wäldern Kalimdors seit Jahren nicht mehr gespürt hatte. Er nahm es sofort als Zeichen, dass etwas nicht stimmte.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Melithar ist oft der Erste, der Neuankömmlinge zu der Dryade schickt, und damit zum ersten Beweis für die Krankheit des Waldes.]=],
		},
		{
			title = "Taten",
			text = [=[• Er sendet Nachricht von Tarindrellas Rückkehr und bittet darum, sie südwestlich von {link:aldrassil}Aldrassil{/link} zu suchen.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Melithar trägt den Familiennamen des Erzdruiden. Keine Chronik verzeichnet, ob oder wie die beiden verwandt sind.]=],
		},
	},
	mentions = {
		{ text = "Die Beschützerin des Waldes" },
	},
	bonds = {
		{ id = "tarindrella", name = "Tarindrella", note = "die Dryade, deren Rückkehr er spürte" },
		{ id = "conservator-ilthalaine", name = "Bewahrer Ilthalaine", note = "dient demselben Tal" },
	},
})

Translate("deDE", "tarindrella", {
	title = "Tarindrella",
	subtitle = "Die Beschützerin des Waldes",
	found = "Südwestlich von Aldrassil, in Shadowglen",
	hint = [=[Sucht die Dryade, die zu den Lichtungen südwestlich von Aldrassil zurückgekehrt ist.]=],
	allegiance = "Die Waldgeister",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Tarindrella ist eine Dryade, eine geheimnisvolle Beschützerin der Wälder, die nach vielen Jahren der Abwesenheit nach {link:shadowglen}Shadowglen{/link} zurückgekehrt ist. Sie kam, weil sich im Wald etwas Böses zusammenbraut. Die Grells und Grellinge des Tals sind dem Bann des Teufelsmooses verfallen, und die friedlichen {link:furbolgs}Furbolgs{/link} der Hügel haben ihre Heimat verlassen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Es war Tarindrella, die als Erste das Teufelsmoos als Ursache des Wahnsinns benannte, der sich unter den Geschöpfen von {link:teldrassil}Teldrassil{/link} ausbreitet.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie beweist, dass die Grells von {link:shadowglen}Shadowglen{/link} das Teufelsmoos in sich tragen.
• Sie schickt Nachricht von der Gefahr an {link:athridas-bearmantle}Athridas Bearmantle{/link} in {link:dolanaar}Dolanaar{/link}.
• Sie deutet die Totems, die in den verlassenen {link:camping}Lagern{/link} der {link:gnarlpine-furbolgs}Knarzklauen{/link} zurückgelassen wurden.]=],
		},
	},
	chapters = {
		{
			title = "Die gravierten Totems",
			hint = [=[Durchsucht die verlassenen Lager der Knarzklauen nach ihren Totems.]=],
			text = [=[Die {link:furbolgs}Furbolgs{/link} ließen ihre Totems im Chaos ihrer Flucht zurück. Ihre Schnitzereien erzählten eine düstere Geschichte. Die {link:gnarlpine-furbolgs}Knarzklauen{/link} hatten begonnen zu träumen, dass ein großer Schatten sie auslöschen würde. Die Furcht wurde zur Raserei, und der Schatten in ihren Träumen nahm die Gestalt ihrer alten Freunde an, der Elfen.]=],
		},
	},
	mentions = {
		{ text = "Die Beschützerin des Waldes" },
		{ text = "Der Ruf der Natur" },
	},
	bonds = {
		{ id = "melithar-staghelm", name = "Melithar Staghelm", note = "spürte ihre Rückkehr" },
		{ id = "athridas-bearmantle", name = "Athridas Bearmantle", note = "der Druide, dem sie Hilfe schickt" },
		{ id = "gnarlpine-furbolgs", name = "Knarzklauen-Furbolgs", note = "der Stamm, dessen Fall sie erforscht" },
	},
})

Translate("deDE", "gilshalan-windwalker", {
	title = "Gilshalan Windwalker",
	subtitle = "Gelehrter der Webwood-Spinnen",
	found = "Am Fuß von Aldrassil, in Shadowglen",
	hint = [=[Sprecht mit dem Gelehrten, der die Spinnen von Shadowglen erforscht.]=],
	allegiance = "Nachtelfen · Darnassus",
	aliases = { "Gilshalan" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Gilshalan Windwalker kam nach {link:shadowglen}Shadowglen{/link}, um die Webwood-Spinnen der Schattenweberhöhle zu erforschen. Sie sind Verwandte einer viel kleineren Art, und er glaubt, dass der Weltbaum sie verändert hat. Er will, dass ihr Gift und ihre Eier nach {link:darnassus}Darnassus{/link} gebracht werden, wo er sie mit ihren kleineren Verwandten vergleichen kann. Er ist ehrlich genug zuzugeben, dass eine lebende Riesenspinne mehr wäre, als er bewältigen könnte.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Gilshalans Studien gehören zu den ersten Versuchen zu erfahren, was der neue Baum mit den Geschöpfen macht, die auf ihm leben.]=],
		},
		{
			title = "Taten",
			text = [=[• Er sammelt das Gift und die Eier der Webwood-Spinnen.
• Er ruft Neuankömmlinge zu {link:tenaron-stormgrip}Tenaron Stormgrip{/link} oben auf {link:aldrassil}Aldrassil{/link}.]=],
		},
	},
	mentions = {
		{ text = "Webwood-Gift" },
		{ text = "Webwood-Ei" },
		{ text = "Tenarons Ruf" },
		{ text = "Fangzahn von Githyiss" },
	},
	bonds = {
		{ id = "tenaron-stormgrip", name = "Tenaron Stormgrip", note = "der Älteste, zu dem er Neuankömmlinge schickt" },
	},
})

