			title = "Taten",
			text = [=[• Sie braut ein Gegengift für das Gift von Githyiss der Abscheulichen.]=],
		},
	},
	mentions = {
		{ text = "Ein guter Freund" },
		{ text = "Iverrons Gegengift" },
		{ text = "Iverrons Gegengift" },
	},
	bonds = {
		{ id = "iverron", name = "Iverron", note = "ihr Freund" },
	},
})

