	},
})

Translate("deDE", "corithras-moonrage", {
	title = "Corithras Moonrage",
	subtitle = "Hüter des Mondbrunnens von Dolanaar",
	found = "Am Mondbrunnen von Dolanaar",
	hint = [=[Sprecht mit dem Elfen, der den Mondbrunnen von Dolanaar hütet.]=],
	allegiance = "Nachtelfen · Zirkel des Cenarius",
	aliases = { "Corithras" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Corithras Moonrage hütet den Mondbrunnen von {link:dolanaar}Dolanaar{/link} und setzt die Erzählung fort, die {link:tenaron-stormgrip}Tenaron{/link} begann. Die Druiden von {link:darnassus}Darnassus{/link} brauchen Mondbrunnenwasser, und Corithras schickt Boten zu den Brunnen von {link:starbreeze-village}Starbreeze{/link}, {link:pools-of-arlithrien}Arlithrien{/link} und der {link:the-oracle-glade}Lichtung des Orakels{/link}, um es zu sammeln. Bei jeder Rückkehr erzählt er ein wenig mehr von der Geschichte.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Von Corithras lernen die jungen Kaldorei den schwersten Teil ihrer jüngeren Geschichte: dass {link:teldrassil}Teldrassil{/link} ohne den Segen der Drachen wuchs.]=],
		},
	},
	chapters = {
		{
			title = "Die Weigerung der Drachen",
			hint = [=[Bringt Corithras Wasser vom Mondbrunnen der Lichtung des Orakels.]=],
			text = [=[Nach dem Krieg waren die Kaldorei ohne Richtung. Der Verräter war befreit, {link:malfurion-stormrage}Malfurion{/link} verschwand, und {link:fandral-staghelm}Fandral Staghelm{/link} übernahm die Führung. Als der Baum gewachsen war, suchte Fandral den Segen der Drachen. Nozdormu wies ihn wegen seiner Anmaßung ab, und {link:alexstrasza}Alexstrasza{/link} pflichtete Nozdormu bei. Corithras tut nicht so, als wären die Folgen gering.]=],
		},
	},
	mentions = {
		{ text = "Die Krone der Erde" },
		{ text = "Die Krone der Erde" },
		{ text = "Die Krone der Erde" },
		{ text = "Die Krone der Erde, das Gefäß für den Erzdruiden" },
	},
	bonds = {
		{ id = "tenaron-stormgrip", name = "Tenaron Stormgrip", note = "begann die Erzählung" },
		{ id = "fandral-staghelm", name = "Fandral Staghelm", note = "empfängt das Wasser" },
	},
})

Translate("deDE", "athridas-bearmantle", {
