		{
			title = "Zusammenfassung",
			text = [=[Denalan ist ein Druide, der von einem Lager am {link:lake-al-ameth}Al'Amethsee{/link} aus die Pflanzen von {link:teldrassil}Teldrassil{/link} erforscht. Er glaubt, dass die Holzlinge, Elementare der Natur, die Gesundheit des Baumes selbst widerspiegeln. Ihr Zorn beunruhigt ihn, und er hat den Boden in Verdacht. Mit besonderen Erden aus {link:darnassus}Darnassus{/link} zieht er ihre Samen, in der Hoffnung, dass sie sanfter sprießen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Denalan ist der geduldigste Erforscher der {link:corruption-of-teldrassil}Verderbnis von Teldrassil{/link}. Wo andere die Krankheit herausschneiden, versucht er, sie zu heilen.]=],
		},
	},
	chapters = {
		{
			title = "Oakenscowl",
			hint = [=[Helft Denalan, die Quelle der Geschwülste der Holzlinge zu finden.]=],
			text = [=[Die Spur führte zu einer Höhle am Südufer des Sees, wo {link:oakenscowl}Oakenscowl{/link}, einst ein edler Anführer der Holzlinge, eine Geschwulst von ungeheurer Größe trug. Die Verderbnis, sagte Denalan, wählt nicht zwischen den Geringen und den Großen.]=],
		},
	},
	mentions = {
		{ text = "Denalans Erde" },
