	},
})

Translate("deDE", "oben-rageclaw", {
	title = "Oben Rageclaw",
	subtitle = "Der schlafende Druide",
	found = "Der Grabhügel von Ban'ethil, als Geist",
	hint = [=[Sucht im Grabhügel von Ban'ethil den Geist des Druiden, der nicht erwachen kann.]=],
	allegiance = "Druiden der Klaue",
