	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Oben Rageclaw war ein Druide, der im {link:ban-ethil-barrow-den}Grabhügel von Ban'ethil{/link} schlief, als die Schamanen der {link:gnarlpine-furbolgs}Knarzklauen{/link} seinen Geist von seinem Körper trennten. Sie hetzten sein leeres Fleisch auf jeden, der den Grabhügel betrat, und ließen seinen Geist im {link:emerald-dream}Smaragdgrünen Traum{/link} gefangen zurück, machtlos, sie aufzuhalten.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Obens Schicksal ist der finsterste Beweis dafür, was die {link:gnarlpine-furbolgs}Knarzklauen{/link} gelernt haben. Er entschied sich, seinen eigenen Körper sterben zu lassen, statt ihnen zu dienen.]=],
		},
	},
	chapters = {
		{
			title = "Der Voodoozauber",
			hint = "Befreit den schlafenden Druiden vom Bann der Knarzklauen.",
			text = [=[Mit einem Zauber, der den Schamanen abgenommen wurde, fand Oben die Antwort. Sein Körper musste erschlagen und der Zauber an ihm angewandt werden. Als es getan war, war sein Geist frei, im Traum zu ruhen.]=],
		},
	},
	mentions = {
		{ text = "Der schlafende Druide" },
		{ text = "Druide der Klaue" },
	},
	bonds = {
		{ id = "gnarlpine-furbolgs", name = "Knarzklauen-Furbolgs", note = "stahlen seinen Körper" },
	},
})

Translate("deDE", "sentinel-arynia-cloudsbreak", {
	title = "Schildwache Arynia Cloudsbreak",
	subtitle = "Wächterin des Orakelbaums",
	found = "Am Mondbrunnen der Lichtung des Orakels",
	hint = [=[Sprecht mit der Schildwache, die den Mondbrunnen der Lichtung des Orakels bewacht.]=],
	allegiance = "Schildwachen",
	aliases = { "Arynia Cloudsbreak", "Arynia" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Schildwache Arynia Cloudsbreak wurde mit einer kleinen Schar von {link:sentinels}Schildwachen{/link} ausgesandt, um den Orakelbaum vor den {link:harpies}Harpyien{/link} zu schützen, die rings um seine Lichtung nisten. Als der Baum eine Läuferin nach {link:darnassus}Darnassus{/link} schickte, töteten die Harpyien sie. Arynias Schar drängt sie Stück für Stück zurück.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie treibt die {link:harpies}Harpyien{/link} der Blutfeder zurück.
• Sie schickt den Bericht des Orakelbaums an den Erzdruiden.
• Sie wird mit ihrer Säbelkatze Mist wiedervereint.]=],
		},
	},
	chapters = {
		{
			title = "Der Makel im Leder",
			hint = "Bringt Arynia die Amulette der Anführerinnen der Harpyien.",
			text = [=[Arynia sah eine Dunkelheit, die sich durch die Gürtel der {link:harpies}Harpyien{/link} zog. Die Amulette ihrer Anführerinnen zeigten grüne Wirbel in den Edelsteinen. Es war das Teufelsmoos, derselbe Makel, von dem aus {link:shadowglen}Shadowglen{/link} berichtet worden war, und sie schickte ihren Vorgesetzten Nachricht.]=],
		},
	},
	mentions = {
		{ text = "Die verzauberte Lichtung" },
		{ text = "{link:teldrassil}Teldrassil{/link}" },
		{ text = "Mist" },
		{ text = "Dunkelheit auf der Lichtung" },
		{ text = "Der Orakelbaum" },
	},
	bonds = {
		{ id = "mist", name = "Mist", note = "ihre Gefährtin" },
		{ id = "fandral-staghelm", name = "Fandral Staghelm", note = "empfängt den Bericht des Baumes" },
	},
})

