	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Oakenscowl war einst ein erhabener Anführer der Holzlinge. Nun wächst an ihm die größte Geschwulst, die {link:denalan}Denalan{/link} je gesehen hat, und von seiner Höhle am Südufer des Al'Amethsees aus breitet sich die Verderbnis auf jedes Geschöpf des Sees aus. Denalan wagte nicht, sich ihm zu nähern, nicht einmal, um ihn zu erforschen.]=],
