Translate("deDE", "gnarlpine-furbolgs", {
	title = "Knarzklauen-Furbolgs",
	aliases = { "Knarzklauen", "Stamm der Knarzklauen" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Knarzklauen sind ein Stamm von {link:furbolgs}Furbolgs{/link}, die als friedliche Freunde der {link:night-elves}Nachtelfen{/link} in den Hügeln von {link:teldrassil}Teldrassil{/link} lebten. Sie haben ihre alte Heimat verlassen und sich unter ihrem Häuptling, {link:ursal-the-mauler}Ursal{/link} dem Zerfleischer, gesammelt, und nun greifen sie eben jene Beschützer an, denen sie einst vertrauten.]=],
		},
		{
			title = "Der Fall des Stammes",
			text = [=[Die Dryade {link:tarindrella}Tarindrella{/link} glaubt, dass nur das Teufelsmoos eine solche Veränderung bewirken konnte. {link:ursal-the-mauler}Ursal{/link} nutzt seine Kräfte, um sein Volk in den Wahnsinn zu treiben. Die Totems, die in ihren verlassenen {link:camping}Lagern{/link} zurückblieben, erzählen mehr. Die Knarzklauen begannen, von einem großen Schatten zu träumen, der sie vernichten würde. Ihre Furcht wurde zur Raserei, und der Schatten in ihren Träumen wurde zu ihren elfischen Freunden.]=],
		},
		{
			title = "Taten des Wahnsinns",
			text = [=[• Sie überfielen den Wärter {link:gaerolas-talvethren}Gaerolas Talvethren{/link} und plünderten {link:starbreeze-village}Starbreeze{/link}.
• Sie drangen in den {link:ban-ethil-barrow-den}Grabhügel von Ban'ethil{/link} ein, und ihre Schamanen lernten, den Geist eines schlafenden Druiden von seinem Körper zu trennen.
• Sie machen Beute auf der Straße nach {link:darnassus}Darnassus{/link} und bei den Streifen an den Teichen von {link:pools-of-arlithrien}Arlithrien{/link}.
• Ihr Mystiker Ferocitas der Traumfresser stahl einen Smaragd, der Kraft aus dem Traum schöpfte.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Noch weiß niemand, woher das Teufelsmoos kam oder ob die {link:furbolgs}Furbolgs{/link} geheilt werden können.]=],
		},
	},
})

Translate("deDE", "corruption-of-teldrassil", {
	title = "Verderbnis von Teldrassil",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Verderbnis von Teldrassil ist die Krankheit, die sich im neuen Weltbaum ausgebreitet hat, seit er gewachsen ist. Die Priesterinnen und Druiden sehen ihre Zeichen überall: in Tieren, in Pflanzen, in {link:furbolgs}Furbolgs{/link} und sogar im Boden.]=],
		},
		{
			title = "Zeichen",
			text = [=[• Seltsame Bestien erheben sich aus dem Boden des Baumes selbst, und Holzlinge werden zornig und schwellen mit giftigen Geschwülsten an.
• Ein Teufelsmoos befällt die Grells von {link:shadowglen}Shadowglen{/link}, die {link:harpies}Harpyien{/link} der {link:the-oracle-glade}Lichtung des Orakels{/link} und die {link:gnarlpine-furbolgs}Knarzklauen-Furbolgs{/link}.
• Der {link:satyrs}Satyr{/link} Xethorr der Verruchte hat die Spinnen des Baumes verdreht, und andere Satyrn schänden seine Mondbrunnen.
• {link:lady-sathrah}Lady Sathrah{/link}, eine von Elune geliebte Spinne, ist wahnsinnig geworden.
• Pflanzen aus fernen Landen sprießen auf dem Baum und reagieren seltsam mit seinem Boden.]=],
		},
		{
			title = "Die Frage nach der Ursache",
			text = [=[{link:corithras-moonrage}Corithras Moonrage{/link} führt viele der Nöte des Baumes darauf zurück, dass er ohne den Segen von Nozdormu und {link:alexstrasza}Alexstrasza{/link} wuchs. {link:fandral-staghelm}Fandral Staghelm{/link} trägt die Last, ein Heilmittel zu finden, und er fürchtet, dass seine Arbeit vielleicht nie vollendet wird. Die Druiden der {link:moonglade}Moonglade{/link} und die von {link:darnassus}Darnassus{/link} misstrauen einander, und die fortdauernde Verderbnis tut nichts, um dieses Misstrauen zu mildern.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik nennt bisher die Quelle des Teufelsmooses oder erklärt, wie der Makel zuerst in den Baum gelangte.]=],
		},
	},
})
